import path from "node:path";
import { writeFileAtomic } from "./store";

// Agents talk to the daemon through their environment: forward Paseo, provider, and locale
// variables, never the daemon's full environment.
const FORWARDED_ENV = [
  "PASEO_*",
  "ANTHROPIC_*",
  "CLAUDE_*",
  "CLAUDECODE",
  "OPENAI_*",
  "CODEX_*",
  "LANG",
  "LC_*",
  "TERM",
  "COLORTERM",
  "TZ",
  "NO_COLOR",
  "FORCE_COLOR",
];

function renderWrapper(stateDirectory: string): string {
  const quotedState = `'${stateDirectory.replaceAll("'", "'\\''")}'`;
  return `#!/bin/sh
# Generated by the workspace-sandbox Paseo plugin and rewritten on every plugin start.
#   sandbox-run agent <command> [args...]   provider launches (derived sandbox profiles)
#   sandbox-run terminal [--title <title>] [command [args...]]
#       terminals the plugin opens in a sandboxed workspace; a login shell when no command is given
set -u
state_dir=${quotedState}

mode=\${1:-}
fail() {
  printf 'workspace-sandbox: %s\\n' "$1" >&2
  # Paseo closes a terminal when its process exits, which would take the message with it.
  if [ "$mode" = terminal ] && [ -t 0 ]; then
    printf 'Press Enter to close this terminal.\\n' >&2
    read -r _ || true
  fi
  exit 126
}

[ $# -gt 0 ] && shift
case $mode in
  agent) workspace_id=\${PASEO_SANDBOX_WORKSPACE_ID:-} ;;
  terminal) workspace_id=\${PASEO_WORKSPACE_ID:-} ;;
  *) fail "unknown mode '$mode'" ;;
esac
case $workspace_id in
  *[!A-Za-z0-9_.-]*) fail "invalid workspace id" ;;
esac
# Paseo names a terminal tab from the title its program sets, else from the command line.
title=
if [ "$mode" = terminal ] && [ "\${1:-}" = --title ]; then
  title=\${2:-}
  shift 2
fi
# Set it first, so the tab shows the right name even when sandbox-run fails.
[ -n "$title" ] && [ -t 1 ] && printf '\\033]0;%s\\007' "$title"

spec=$state_dir/workspaces/$workspace_id.sh
if [ -z "$workspace_id" ] || [ ! -f "$spec" ]; then
  # Only the plugin opens sandboxed terminals, and only in sandboxed workspaces.
  [ "$mode" = terminal ] && fail "workspace \${workspace_id:-?} is not sandboxed"
  # Every agent session carries PASEO_AGENT_ID, and a session never falls back to the host. Runs
  # without a session (model discovery, version checks) and history the plugin routes here (agents
  # whose sandbox is gone) run the host's CLI, which is assumed to match the sandboxes'.
  if [ -n "\${PASEO_AGENT_ID:-}" ] && [ "\${PASEO_SANDBOX_ROUTE:-}" != host ]; then
    fail "agent $PASEO_AGENT_ID is not in a sandboxed workspace"
  fi
  [ $# -gt 0 ] || fail "missing command"
  exec "$@"
fi

. "$spec"

# The plugin starts and recreates containers, and waits for this one before letting an agent or
# terminal launch, so it should be running.
running=$("$sandbox_cli" container inspect --format '{{.State.Running}}' "$sandbox_container" 2>/dev/null)
[ "$running" = true ] || fail "the sandbox is not running; start the agent or terminal again from Paseo, which starts it"

case $PWD in
  "$sandbox_workdir" | "$sandbox_workdir"/*) workdir=$PWD ;;
  *) workdir=$sandbox_workdir ;;
esac

env_args=
for name in $(env | sed -n 's/^\\([A-Za-z_][A-Za-z0-9_]*\\)=.*/\\1/p'); do
  case $name in
    ${FORWARDED_ENV.join(" | ")}) env_args="$env_args -e $name" ;;
  esac
done

tty_flag=
[ -t 0 ] && [ -t 1 ] && tty_flag=-t

# The sandboxed terminal's shell. Commands started without it (agents, terminal profiles) get the
# environment it builds, captured once per container: running it per launch would be slow, and
# whatever the dotfiles print would reach the agent's protocol stream.
login_shell='if command -v bash >/dev/null 2>&1; then exec bash -il "$@"; fi; exec sh -il "$@"'
# See environmentFile in store.ts.
env_file=\${spec%.sh}.env

capture_env() {
  container_id=$("$sandbox_cli" container inspect --format '{{.Id}}' "$sandbox_container" 2>/dev/null)
  [ -n "$container_id" ] || return 0
  [ "$(head -n 1 "$env_file" 2>/dev/null)" = "#container=$container_id" ] && return 0
  [ "$mode" = terminal ] && printf 'workspace-sandbox: reading the login shell environment...\\n' >&2
  marker=__paseo_sandbox_env_$$__
  # NUL-separated where env supports it, so a value spanning lines is dropped, not misread.
  capture="printf '%s\\n' $marker; if env -0 >/dev/null 2>&1; then env -0 | tr '\\n\\000' '\\001\\n'; else env; fi; printf '%s\\n' $marker"
  limit=
  command -v timeout >/dev/null 2>&1 && limit="timeout 60"
  # shellcheck disable=SC2086
  output=$($limit "$sandbox_cli" exec -w "$workdir" "$sandbox_container" \\
    sh -c "$login_shell" sh -c "$capture" </dev/null 2>/dev/null)
  if [ "$(printf '%s\\n' "$output" | grep -c "^$marker\\$")" -ne 2 ]; then
    printf 'workspace-sandbox: could not read the login shell environment\\n' >&2
    return 0
  fi
  tmp=$env_file.$$
  # It may hold secrets the dotfiles export, so only you can read it.
  (
    umask 077
    {
      printf '#container=%s\\n' "$container_id"
      printf '%s\\n' "$output" | sed -n "/^$marker\\$/,/^$marker\\$/p" | sed '1d;$d' |
        grep -v "$(printf '\\001')" | grep -E '^[A-Za-z_][A-Za-z0-9_]*=' |
        grep -Ev '^(PWD|OLDPWD|SHLVL|_|TERM|PS1|PS2|PS4|COLUMNS|LINES)='
    } >"$tmp"
  ) && mv "$tmp" "$env_file"
}

env_file_arg=
if [ "$mode" = terminal ] && [ $# -eq 0 ]; then
  set -- sh -c "$login_shell" sh
else
  capture_env
  [ -f "$env_file" ] && env_file_arg=$env_file
fi
[ $# -gt 0 ] || fail "missing command"

# Killing \`exec\`'s client does not stop the process inside the container, so record its pid and
# forward signals to it. Background jobs read /dev/null unless stdin is passed explicitly.
pid_file=/tmp/paseo-sandbox-$$.pid
exec 3<&0
# Forwarded variables come after the env file, so this launch's values win.
# shellcheck disable=SC2086
"$sandbox_cli" exec -i $tty_flag \${env_file_arg:+--env-file} \${env_file_arg:+"$env_file_arg"} $env_args \\
  -w "$workdir" "$sandbox_container" \\
  sh -c 'echo $$ > "$0"; exec "$@"' "$pid_file" "$@" <&3 3<&- &
child=$!
exec 3<&-

forward() {
  "$sandbox_cli" exec "$sandbox_container" sh -c 'kill -s "$1" "$(cat "$0")" 2>/dev/null' "$pid_file" "$1" >/dev/null 2>&1
}
trap 'forward TERM' TERM
trap 'forward INT' INT
trap 'forward HUP' HUP

status=0
while :; do
  wait "$child"
  status=$?
  kill -0 "$child" 2>/dev/null || break
done
"$sandbox_cli" exec "$sandbox_container" rm -f "$pid_file" >/dev/null 2>&1
exit "$status"
`;
}

export async function writeWrapper(stateDirectory: string): Promise<string> {
  const file = path.join(stateDirectory, "bin", "sandbox-run");
  await writeFileAtomic(file, renderWrapper(stateDirectory), 0o755);
  return file;
}
